//! Character display width (East Asian context), modeled after the classic
//! unicode-width 0.1.x semantics: ambiguous characters are wide, NUL is zero
//! width, other control characters have no width at all.

use crate::width_table::WIDTH_TABLE;

fn lookup(cp: u32) -> (u8, u8) {
    let mut lo = 0usize;
    let mut hi = WIDTH_TABLE.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b, w, wc) = WIDTH_TABLE[mid];
        if cp < a {
            hi = mid;
        } else if cp > b {
            lo = mid + 1;
        } else {
            return (w, wc);
        }
    }
    (1, 1)
}

/// Width of a character in an East Asian (CJK) context. `None` means the
/// character is a control character which cannot be displayed.
pub fn char_width_cjk(c: char) -> Option<usize> {
    let cp = c as u32;
    if cp < 0x7f {
        if cp >= 0x20 {
            Some(1)
        } else if cp == 0 {
            Some(0)
        } else {
            None
        }
    } else if cp >= 0xa0 {
        Some(lookup(cp).1 as usize)
    } else {
        None
    }
}
EOF
echo ok"}

