                _ => InputSeq::new(KeySeq::Unidentified),
            },
            _ => match first {
                Some(1) | Some(7) => InputSeq::new(KeySeq::HomeKey),
                Some(4) | Some(8) => InputSeq::new(KeySeq::EndKey),
                Some(3) => InputSeq::new(KeySeq::DeleteKey),
                Some(5) => InputSeq::new(KeySeq::PageUpKey),
                Some(6) => InputSeq::new(KeySeq::PageDownKey),
                _ => InputSeq::new(KeySeq::Unidentified),
            },
        })
    }

    fn decode_escape(&mut self) -> io::Result<InputSeq> {
        let b = self.read_byte()?;
        match b {
            b'[' => self.decode_csi(),
            0x00..=0x1f | 0x7f => Ok(InputSeq::new(KeySeq::Key(0x1b))),
