        let b = self.read_byte()?;
        match b {
            0x1b => self.decode_escape(),
            0x00..=0x7f => Ok(InputSeq::new(KeySeq::Key(b))),
            _ => {
                let c = self.read_utf8(b)?;
                Ok(InputSeq::new(KeySeq::Utf8Key(c)))
            }
        }
    }
}
