//! Helpers to report fatal internal errors in the same shape as a Rust panic.

use std::fmt;

pub struct FakePanic {
    pub location: &'static str,
    pub message: String,
}

impl fmt::Display for FakePanic {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

pub fn install_hook() {
    std::panic::set_hook(Box::new(|info| {
        let pid = std::process::id();
        if let Some(fp) = info.payload().downcast_ref::<FakePanic>() {
            eprintln!(
                "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
                pid, fp.location, fp.message
            );
            return;
        }
        let msg = if let Some(s) = info.payload().downcast_ref::<&str>() {
            s.to_string()
        } else if let Some(s) = info.payload().downcast_ref::<String>() {
            s.clone()
        } else {
            "Box<dyn Any>".to_string()
        };
        let loc = match info.location() {
            Some(l) => format!("{}:{}:{}", l.file(), l.line(), l.column()),
            None => "<unknown>".to_string(),
        };
        eprintln!(
            "\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
            pid, loc, msg
        );
    }));
}

pub fn fake_panic(location: &'static str, message: String) -> ! {
    std::panic::panic_any(FakePanic { location, message })
}

pub fn unreachable_input() -> ! {
    fake_panic("src/input.rs:254:18", "internal error: entered unreachable code".to_string())
}

pub fn unwrap_none_highlight() -> ! {
    fake_panic(
        "src/highlight.rs:579:53",
        "called `Option::unwrap()` on a `None` value".to_string(),
    )
}

/// Message produced by `&s[..idx]` when `idx` is out of bounds.
pub fn slice_out_of_bounds(location: &'static str, idx: usize, s: &str) -> ! {
    fake_panic(location, format!("byte index {} is out of bounds of `{}`", idx, s))
}

/// Message produced by `&s[..idx]` when `idx` is not on a char boundary.
pub fn slice_not_boundary(location: &'static str, idx: usize, s: &str) -> ! {
    // find the char containing idx
    let mut start = idx;
    while !s.is_char_boundary(start) {
        start -= 1;
    }
    let ch = s[start..].chars().next().unwrap_or('\0');
    let end = start + ch.len_utf8();
    fake_panic(
        location,
        format!(
            "byte index {} is not a char boundary; it is inside {:?} (bytes {}..{}) of `{}`",
            idx, ch, start, end, s
        ),
    )
}
