fn is_sep(c: char) -> bool {
    c.is_ascii() && !c.is_ascii_alphanumeric() && c != '_'
}

fn starts_with(chars: &[char], i: usize, pat: &str) -> bool {
    let mut j = i;
    for pc in pat.chars() {
        if j >= chars.len() || chars[j] != pc {
            return false;
        }
        j += 1;
    }
    true
}

fn char_literal_len(chars: &[char], i: usize) -> Option<usize> {
    let len = chars.len();
    if i + 1 < len && chars[i + 1] == '\\' && i + 3 < len && chars[i + 3] == '\'' {
        return Some(4);
    }
    if i + 2 < len && chars[i + 2] == '\'' {
        return Some(3);
    }
    None
}

fn ident_end(chars: &[char], i: usize) -> usize {
    let mut j = i;
    while j < chars.len() && !is_sep(chars[j]) {
        j += 1;
    }
    j
}

fn scan_number(spec: &LangSpec, chars: &[char], i: usize) -> usize {
    let len = chars.len();
    let us = spec.underscore;
    let at = |k: usize| -> Option<char> { chars.get(k).copied() };
    let is_hex = |c: char| c.is_ascii_hexdigit() || (us && c == '_');
    let is_bin = |c: char| c == '0' || c == '1' || (us && c == '_');
    if at(i) == Some('0') && at(i + 1) == Some('x') && at(i + 2).map_or(false, is_hex) {
        let mut j = i + 2;
        while j < len && is_hex(chars[j]) {
            j += 1;
        }
        return j - i;
    }
    if spec.binary && at(i) == Some('0') && at(i + 1) == Some('b') && at(i + 2).map_or(false, is_bin) {
        let mut j = i + 2;
        while j < len && is_bin(chars[j]) {
            j += 1;
        }
        return j - i;
    }
    let mut j = i;
    while j < len && (chars[j].is_ascii_digit() || (us && chars[j] == '_')) {
        j += 1;
    }
    if j < len && chars[j] == '.' {
        j += 1;
        if j < len && chars[j].is_ascii_digit() {
            j += scan_number(spec, chars, j);
        }
    }
    j - i
}

fn keyword_hl(spec: &LangSpec, word: &str) -> Option<Highlight> {
    if spec.control.contains(&word) {
        Some(Highlight::Control)
    } else if spec.keywords.contains(&word) {
        Some(Highlight::Keyword)
    } else if spec.types.contains(&word) {
        Some(Highlight::Type)
    } else if spec.bools.contains(&word) {
        Some(Highlight::Number)
    } else if spec.specials.contains(&word) {
        Some(Highlight::Special)
    } else {
        None
    }
}

/// Highlight one line. Returns the highlights and the state at the end of the line.
pub fn highlight_line(lang: Language, chars: &[char], state_in: HlState) -> (Vec<Highlight>, HlState) {
    let len = chars.len();
    let mut hl = vec![Highlight::Normal; len];
    let spec = match spec_for(lang) {
        Some(s) => s,
        None => return (hl, HlState::None),
    };
    let mut state = state_in;
    let mut i = 0;
    let mut prev_sep = true;
    let mut def_ctx = false;

    while i < len {
        let c = chars[i];

        if state == HlState::Comment {
            if let Some((_, end)) = spec.block_comment {
                if starts_with(chars, i, end) {
                    for k in 0..end.chars().count() {
                        hl[i + k] = Highlight::Comment;
                    }
                    i += end.chars().count();
                    state = HlState::None;
                    prev_sep = true;
                    continue;
                }
            }
            hl[i] = Highlight::Comment;
            i += 1;
            continue;
        }

        if spec.char_literal && c == '\'' {
            if let Some(n) = char_literal_len(chars, i) {
                for k in 0..n {
                    hl[i + k] = Highlight::String;
                }
                i += n;
                prev_sep = true;
                def_ctx = false;
                continue;
            }
        }

        if let HlState::String(q) = state {
            hl[i] = Highlight::String;
            if c == q && !(i > 0 && chars[i - 1] == '\\') {
                state = HlState::None;
                prev_sep = true;
            }
            i += 1;
            continue;
        }

        if def_ctx {
            if c == ' ' || c == '\t' {
                hl[i] = Highlight::Normal;
                i += 1;
                continue;
            }
            if !is_sep(c) {
                let end = ident_end(chars, i);
                let word: String = chars[i..end].iter().collect();
                if let Some(h) = keyword_hl(spec, &word) {
                    for k in i..end {
                        hl[k] = h;
                    }
                } else {
                    let bytes = word.len();
                    for k in 0..bytes {
                        if i + k >= len {
                            crate::panic_like::unwrap_none_highlight();
                        }
                        hl[i + k] = Highlight::Definition;
                    }
                }
                i = end;
                prev_sep = false;
                continue;
            }
            def_ctx = false;
        }

        if let Some(lc) = spec.line_comment {
            if starts_with(chars, i, lc) {
                for k in i..len {
                    hl[k] = Highlight::Comment;
                }
                break;
            }
        }

        if let Some((start, _)) = spec.block_comment {
            if starts_with(chars, i, start) {
                let n = start.chars().count();
                for k in 0..n {
                    hl[i + k] = Highlight::Comment;
                }
                i += n;
                state = HlState::Comment;
                continue;
            }
        }

        if spec.string_quotes.contains(&c) {
            hl[i] = Highlight::String;
            state = HlState::String(c);
            i += 1;
            continue;
        }

        if c.is_ascii_digit() && prev_sep {
            let n = scan_number(spec, chars, i);
            for k in 0..n {
                hl[i + k] = Highlight::Number;
            }
            i += n;
            prev_sep = false;
            continue;
        }

        if prev_sep && !is_sep(c) {
            let end = ident_end(chars, i);
            let word: String = chars[i..end].iter().collect();
            if let Some(h) = keyword_hl(spec, &word) {
                for k in i..end {
                    hl[k] = h;
                }
                if spec.defs.contains(&word.as_str()) {
                    def_ctx = true;
                }
            }
            i = end;
            prev_sep = false;
            continue;
        }

        hl[i] = Highlight::Normal;
        prev_sep = is_sep(c);
        i += 1;
    }

    (hl, state)
}
