//! Undo/redo history.

#[derive(Clone, Debug)]
pub enum ChangeKind {
    /// Insert a character at (x, y).
    InsertChar(char),
    /// Delete the character at (x, y). `x` is the index of the removed char.
    DeleteChar(char),
    /// Split row `y` at `x`.
    Newline,
    /// Join row `y` with row `y + 1` (remove the newline at the end of row y).
    DeleteNewline,
    /// Insert an empty row at `y`.
    InsertRow,
    /// Delete `text` starting at (x, y) within one row.
    DeleteText(Vec<char>),
}

#[derive(Clone, Debug)]
pub struct Change {
    pub kind: ChangeKind,
    pub x: usize,
    pub y: usize,
    pub before: (usize, usize),
    pub after: (usize, usize),
}

#[derive(Default)]
pub struct History {
    groups: Vec<Vec<Change>>,
    index: usize,
    pending: Vec<Change>,
    saved_index: usize,
}

impl History {
    pub fn new() -> Self {
        History::default()
    }

    pub fn commit(&mut self) {
        if !self.pending.is_empty() {
            self.groups.truncate(self.index);
            let g = std::mem::take(&mut self.pending);
            self.groups.push(g);
            self.index = self.groups.len();
        }
    }

    pub fn push(&mut self, change: Change) {
        if self.pending.is_empty() {
            // a new pending group invalidates the redo stack
            self.groups.truncate(self.index);
        }
        self.pending.push(change);
    }

    pub fn is_modified(&self) -> bool {
        self.index != self.saved_index || !self.pending.is_empty()
    }

    pub fn mark_saved(&mut self) {
        self.commit();
        self.saved_index = self.index;
    }

    /// Returns the group to undo (changes in application order), if any.
    pub fn undo(&mut self) -> Option<Vec<Change>> {
        self.commit();
        if self.index == 0 {
            return None;
        }
        self.index -= 1;
        Some(self.groups[self.index].clone())
    }

    pub fn redo(&mut self) -> Option<Vec<Change>> {
        self.commit();
        if self.index >= self.groups.len() {
            return None;
        }
        let g = self.groups[self.index].clone();
        self.index += 1;
        Some(g)
    }
}
