//! Text buffer: rows, cursor, scrolling state, undo history and file I/O.

use std::fs;
use std::io::{self, Write};

use crate::highlight::{highlight_line, Highlight, HlState};
use crate::history::{Change, ChangeKind, History};
use crate::language::Language;
use crate::width::char_width_cjk;

pub const TAB_STOP: usize = 8;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum CharKind {
    Space,
    Punct,
    Ident,
}

pub fn char_kind(c: char) -> CharKind {
    if c.is_whitespace() {
        CharKind::Space
    } else if c.is_alphanumeric() || c == '_' {
        CharKind::Ident
    } else {
        CharKind::Punct
    }
}

pub struct TextBuffer {
    pub rows: Vec<Vec<char>>,
    hls: Vec<Vec<Highlight>>,
    states: Vec<HlState>,
    hl_dirty: Option<usize>,
    pub cx: usize,
    pub cy: usize,
    pub rowoff: usize,
    pub coloff: usize,
    pub path: Option<String>,
    pub lang: Language,
    history: History,
    /// First row which needs to be redrawn (accumulated between renders).
    pub dirty_start: Option<usize>,
}

fn validate_text(text: &str) -> io::Result<Vec<Vec<char>>> {
    let mut rows = Vec::new();
    for line in text.lines() {
        let mut row = Vec::with_capacity(line.len());
        for c in line.chars() {
            if c != '\t' && char_width_cjk(c).is_none() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    format!("Invalid character for text is included: {:?}", c),
                ));
            }
            row.push(c);
        }
        rows.push(row);
    }
    Ok(rows)
}

impl TextBuffer {
    pub fn empty() -> Self {
        let mut b = TextBuffer {
            rows: vec![Vec::new()],
            hls: Vec::new(),
            states: Vec::new(),
            hl_dirty: Some(0),
            cx: 0,
            cy: 0,
            rowoff: 0,
            coloff: 0,
            path: None,
            lang: Language::Plain,
            history: History::new(),
            dirty_start: Some(0),
        };
        b.update_highlight();
        b
    }

    pub fn open(path: &str) -> io::Result<Self> {
        let lang = Language::detect(path);
        let rows = match fs::metadata(path) {
            Ok(_) => {
                let text = fs::read_to_string(path)?;
                validate_text(&text)?
            }
            Err(_) => vec![Vec::new()],
        };
        let mut b = TextBuffer {
            rows,
            hls: Vec::new(),
            states: Vec::new(),
            hl_dirty: Some(0),
            cx: 0,
            cy: 0,
            rowoff: 0,
            coloff: 0,
            path: Some(path.to_string()),
            lang,
            history: History::new(),
            dirty_start: Some(0),
        };
        b.update_highlight();
        Ok(b)
    }

    pub fn num_rows(&self) -> usize {
        self.rows.len()
    }

    pub fn is_modified(&self) -> bool {
        self.history.is_modified()
    }

    pub fn display_name(&self) -> &str {
        match &self.path {
            Some(p) => p.as_str(),
            None => "[No Name]",
        }
    }

    pub fn row_len(&self, y: usize) -> usize {
        self.rows.get(y).map_or(0, |r| r.len())
    }

    pub fn char_at(&self, x: usize, y: usize) -> Option<char> {
        self.rows.get(y).and_then(|r| r.get(x)).copied()
    }

    fn mark_dirty(&mut self, y: usize) {
        self.dirty_start = Some(match self.dirty_start {
            Some(d) => d.min(y),
            None => y,
        });
        self.hl_dirty = Some(match self.hl_dirty {
            Some(d) => d.min(y),
            None => y,
        });
    }

    pub fn mark_all_dirty(&mut self) {
        self.dirty_start = Some(0);
    }

    pub fn update_highlight(&mut self) {
        let start = match self.hl_dirty.take() {
            Some(s) => s,
            None => return,
        };
        self.hls.truncate(start);
        self.states.truncate(start);
        let mut state = if start == 0 { HlState::None } else { self.states[start - 1] };
        for y in start..self.rows.len() {
            let (hl, st) = highlight_line(self.lang, &self.rows[y], state);
            self.hls.push(hl);
            self.states.push(st);
            state = st;
        }
    }

    pub fn highlight_of(&self, y: usize) -> &[Highlight] {
        &self.hls[y]
    }

    /// Rendered column of the character index `cx` on row `cy`.
    pub fn rx_of(&self, cx: usize, cy: usize) -> usize {
        let row = match self.rows.get(cy) {
            Some(r) => r,
            None => return 0,
        };
        if cx > row.len() {
            let s: String = row.iter().collect();
            crate::panic_like::slice_out_of_bounds("src/row.rs:125:13", cx, &s);
        }
        let mut rx = 0;
        for &c in &row[..cx] {
            rx += char_render_width(c, rx);
        }
        rx
    }

    pub fn rx(&self) -> usize {
        self.rx_of(self.cx, self.cy)
    }

    // ---- cursor movement -------------------------------------------------

    fn clamp_cx(&mut self) {
        let len = self.row_len(self.cy);
        if self.cx > len {
            self.cx = len;
        }
    }

    pub fn move_left(&mut self) {
        if self.cx > 0 {
            self.cx -= 1;
        } else if self.cy > 0 {
            self.cy -= 1;
            self.cx = self.row_len(self.cy);
        }
    }

    pub fn move_right(&mut self) {
        if self.cy >= self.rows.len() {
            return;
        }
        let len = self.rows[self.cy].len();
        if self.cx < len {
            self.cx += 1;
        } else {
            self.cy += 1;
            self.cx = 0;
        }
    }

    pub fn move_up(&mut self) {
        if self.cy > 0 {
            self.cy -= 1;
            self.clamp_cx();
        }
    }

    pub fn move_down(&mut self) {
        if self.cy < self.rows.len() {
            self.cy += 1;
            self.clamp_cx();
        }
    }

    pub fn move_home(&mut self) {
        self.cx = 0;
    }

    pub fn move_end(&mut self) {
        if self.cy < self.rows.len() {
            self.cx = self.rows[self.cy].len();
        }
    }

    pub fn move_top(&mut self) {
        self.cy = 0;
    }

    pub fn move_bottom(&mut self) {
        self.cy = self.rows.len();
    }

    pub fn page_up(&mut self, text_rows: usize) {
        self.cy = self.rowoff;
        for _ in 0..text_rows {
            self.move_up();
        }
    }

    pub fn page_down(&mut self, text_rows: usize) {
        self.cy = self.rowoff + text_rows - 1;
        if self.cy > self.rows.len() {
            self.cy = self.rows.len();
        }
        for _ in 0..text_rows {
            self.move_down();
        }
    }

    fn kind_at_cursor(&self) -> CharKind {
        match self.char_at(self.cx, self.cy) {
            Some(c) => char_kind(c),
            None => CharKind::Space,
        }
    }

    fn at_buffer_end(&self) -> bool {
        self.cy >= self.rows.len()
    }

    pub fn next_word(&mut self) {
        if self.at_buffer_end() {
            return;
        }
        self.move_right();
        let kind = self.kind_at_cursor();
        if kind != CharKind::Space {
            while !self.at_buffer_end() && self.kind_at_cursor() == kind {
                self.move_right();
            }
        }
        while !self.at_buffer_end() && self.kind_at_cursor() == CharKind::Space {
            self.move_right();
        }
    }

    pub fn prev_word(&mut self) {
        if self.cx == 0 && self.cy == 0 {
            return;
        }
        self.move_left();
        while !(self.cx == 0 && self.cy == 0) && self.kind_at_cursor() == CharKind::Space {
            self.move_left();
        }
        let kind = self.kind_at_cursor();
        loop {
            if self.cx == 0 && self.cy == 0 {
                break;
            }
            self.move_left();
            if self.cx == 0 && self.cy == 0 {
                break;
            }
            if self.kind_at_cursor() != kind {
                self.move_right();
                break;
            }
        }
    }

    pub fn next_paragraph(&mut self) {
        while self.cy < self.rows.len() && !self.rows[self.cy].is_empty() {
            self.move_down();
        }
        while self.cy < self.rows.len() && self.rows[self.cy].is_empty() {
            self.move_down();
        }
    }

    pub fn prev_paragraph(&mut self) {
        if self.cy == 0 {
            return;
        }
        self.move_up();
        while self.cy > 0 && self.row_len(self.cy) == 0 {
            self.move_up();
        }
        while self.cy > 0 && self.row_len(self.cy - 1) != 0 {
            self.move_up();
        }
    }

    // ---- editing -----------------------------------------------------------

    fn apply(&mut self, change: &Change) {
        let (x, y) = (change.x, change.y);
        match &change.kind {
            ChangeKind::InsertChar(c) => {
                self.rows[y].insert(x, *c);
            }
            ChangeKind::DeleteChar(_) => {
                self.rows[y].remove(x);
            }
            ChangeKind::Newline => {
                let rest = self.rows[y].split_off(x);
                self.rows.insert(y + 1, rest);
            }
            ChangeKind::DeleteNewline => {
                let next = self.rows.remove(y + 1);
                self.rows[y].extend(next);
            }
            ChangeKind::InsertRow => {
                self.rows.insert(y, Vec::new());
            }
            ChangeKind::DeleteText(text) => {
                self.rows[y].drain(x..x + text.len());
            }
        }
        self.mark_dirty(y);
    }

    fn revert(&mut self, change: &Change) {
        let (x, y) = (change.x, change.y);
        match &change.kind {
            ChangeKind::InsertChar(_) => {
                self.rows[y].remove(x);
            }
            ChangeKind::DeleteChar(c) => {
                self.rows[y].insert(x, *c);
            }
            ChangeKind::Newline => {
                let next = self.rows.remove(y + 1);
                self.rows[y].extend(next);
            }
            ChangeKind::DeleteNewline => {
                let rest = self.rows[y].split_off(x);
                self.rows.insert(y + 1, rest);
            }
            ChangeKind::InsertRow => {
                self.rows.remove(y);
            }
            ChangeKind::DeleteText(text) => {
                let row = &mut self.rows[y];
                for (i, c) in text.iter().enumerate() {
                    row.insert(x + i, *c);
                }
            }
        }
        self.mark_dirty(y);
    }

    fn record(&mut self, kind: ChangeKind, x: usize, y: usize, before: (usize, usize), after: (usize, usize)) {
        let change = Change { kind, x, y, before, after };
        self.apply(&change);
        self.history.push(change);
        self.cx = after.0;
        self.cy = after.1;
    }

    pub fn insert_char(&mut self, c: char) {
        if self.cy >= self.rows.len() {
            let y = self.rows.len();
            self.record(ChangeKind::InsertRow, 0, y, (self.cx, self.cy), (self.cx, self.cy));
        }
        let (x, y) = (self.cx, self.cy);
        self.record(ChangeKind::InsertChar(c), x, y, (x, y), (x + 1, y));
    }

    pub fn insert_newline(&mut self) {
        self.history.commit();
        let (x, y) = (self.cx, self.cy);
        if y >= self.rows.len() {
            self.record(ChangeKind::InsertRow, 0, y, (x, y), (0, y));
            return;
        }
        self.record(ChangeKind::Newline, x, y, (x, y), (0, y + 1));
    }

    /// Backspace.
    pub fn delete_char(&mut self) {
        let (x, y) = (self.cx, self.cy);
        if y >= self.rows.len() {
            return;
        }
        if x > 0 {
            let c = self.rows[y][x - 1];
            self.history.commit();
            self.record(ChangeKind::DeleteChar(c), x - 1, y, (x, y), (x - 1, y));
        } else if y > 0 {
            let prev_len = self.rows[y - 1].len();
            self.history.commit();
            self.record(ChangeKind::DeleteNewline, prev_len, y - 1, (0, y), (prev_len, y - 1));
        }
    }

    /// Delete key: delete the character under the cursor.
    pub fn delete_right_char(&mut self) {
        if self.cy >= self.rows.len() {
            return;
        }
        if self.cy == self.rows.len() - 1 && self.cx >= self.rows[self.cy].len() {
            return;
        }
        self.move_right();
        self.delete_char();
    }

    pub fn delete_until_end_of_line(&mut self) {
        let (x, y) = (self.cx, self.cy);
        if y >= self.rows.len() {
            return;
        }
        let len = self.rows[y].len();
        if x < len {
            let text: Vec<char> = self.rows[y][x..].to_vec();
            self.history.commit();
            self.record(ChangeKind::DeleteText(text), x, y, (x, y), (x, y));
        } else if y + 1 < self.rows.len() {
            self.history.commit();
            self.record(ChangeKind::DeleteNewline, x, y, (x, y), (x, y));
        }
    }

    pub fn delete_until_head_of_line(&mut self) {
        let (x, y) = (self.cx, self.cy);
        if y >= self.rows.len() {
            return;
        }
        if x > 0 {
            let text: Vec<char> = self.rows[y][..x].to_vec();
            self.history.commit();
            self.record(ChangeKind::DeleteText(text), 0, y, (x, y), (0, y));
        } else if y > 0 {
            let prev_len = self.rows[y - 1].len();
            self.history.commit();
            self.record(ChangeKind::DeleteNewline, prev_len, y - 1, (0, y), (prev_len, y - 1));
        }
    }

    pub fn delete_word(&mut self) {
        let (x, y) = (self.cx, self.cy);
        if y >= self.rows.len() || x == 0 {
            return;
        }
        let row = &self.rows[y];
        let mut start = x;
        while start > 0 && row[start - 1].is_whitespace() {
            start -= 1;
        }
        while start > 0 && !row[start - 1].is_whitespace() {
            start -= 1;
        }
        if start == x {
            return;
        }
        let text: Vec<char> = row[start..x].to_vec();
        self.history.commit();
        self.record(ChangeKind::DeleteText(text), start, y, (x, y), (start, y));
    }

    /// Returns false when there is nothing to undo.
    pub fn undo(&mut self) -> bool {
        match self.history.undo() {
            None => false,
            Some(group) => {
                for change in group.iter().rev() {
                    self.revert(change);
                }
                if let Some(first) = group.first() {
                    self.cx = first.before.0;
                    self.cy = first.before.1;
                }
                true
            }
        }
    }

    pub fn redo(&mut self) -> bool {
        match self.history.redo() {
            None => false,
            Some(group) => {
                for change in group.iter() {
                    self.apply(change);
                }
                if let Some(last) = group.last() {
                    self.cx = last.after.0;
                    self.cy = last.after.1;
                }
                true
            }
        }
    }

    pub fn finish_edit(&mut self) {
        self.history.commit();
    }

    // ---- file ----------------------------------------------------------------

    pub fn set_path(&mut self, path: String) {
        self.lang = Language::detect(&path);
        self.path = Some(path);
        self.hl_dirty = Some(0);
        self.update_highlight();
    }

    /// Writes the buffer to its file. Returns the number of bytes written.
    pub fn save(&mut self) -> io::Result<usize> {
        let path = match &self.path {
            Some(p) => p.clone(),
            None => return Err(io::Error::new(io::ErrorKind::Other, "no file name")),
        };
        let mut text = String::new();
        for row in &self.rows {
            text.extend(row.iter());
            text.push('\n');
        }
        let mut f = fs::File::create(&path)?;
        f.write_all(text.as_bytes())?;
        self.history.mark_saved();
        Ok(text.len())
    }

    // ---- search helpers -----------------------------------------------------

    pub fn row_string(&self, y: usize) -> String {
        self.rows[y].iter().collect()
    }
}

/// Width of a character rendered at column `col`.
pub fn char_render_width(c: char, col: usize) -> usize {
    if c == '\t' {
        TAB_STOP - (col % TAB_STOP)
    } else {
        char_width_cjk(c).unwrap_or(0)
    }
}
