//! Terminal colors and escape sequence helpers.

use crate::highlight::Highlight;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ColorMode {
    Basic,
    Colors256,
    TrueColor,
}

impl ColorMode {
    pub fn detect() -> ColorMode {
        if std::env::var("COLORTERM").map_or(false, |v| v == "truecolor") {
            return ColorMode::TrueColor;
        }
        if std::env::var("TERM").map_or(false, |v| v.ends_with("-256color")) {
            return ColorMode::Colors256;
        }
        ColorMode::Basic
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Reset,
    NonText,
    Comment,
    Type,
    Number,
    String,
    Control,
    Keyword,
    Special,
    Definition,
    Match,
    CurrentMatch,
    ErrorMessage,
}

impl Color {
    pub fn from_highlight(hl: Highlight) -> Color {
        match hl {
            Highlight::Normal => Color::Reset,
            Highlight::Number => Color::Number,
            Highlight::String => Color::String,
            Highlight::Comment => Color::Comment,
            Highlight::Keyword => Color::Keyword,
            Highlight::Control => Color::Control,
            Highlight::Type => Color::Type,
            Highlight::Special => Color::Special,
            Highlight::Definition => Color::Definition,
            Highlight::Match => Color::Match,
            Highlight::CurrentMatch => Color::CurrentMatch,
        }
    }

    pub fn sequence(self, mode: ColorMode) -> &'static str {
        match mode {
            ColorMode::Basic => match self {
                Color::Reset => "\x1b[39;0m",
                Color::NonText => "\x1b[37m",
                Color::Comment => "\x1b[90m",
