//! Terminal colors and escape sequence helpers.

use crate::highlight::Highlight;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ColorMode {
    Basic,
    Colors256,
    TrueColor,
}

impl ColorMode {
    pub fn detect() -> ColorMode {
        if std::env::var("COLORTERM").map_or(false, |v| v == "truecolor") {
            return ColorMode::TrueColor;
        }
        if std::env::var("TERM").map_or(false, |v| v.ends_with("-256color")) {
            return ColorMode::Colors256;
        }
        ColorMode::Basic
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Reset,
    NonText,
    Comment,
    Type,
    Number,
    String,
    Control,
    Keyword,
    Special,
    Definition,
    Match,
    CurrentMatch,
    ErrorMessage,
}

