//! The editor: main loop, key handling, prompts, search and rendering.

use std::io::{self, Write};
use std::time::Instant;

use crate::highlight::Highlight;
use crate::input::{InputSeq, KeySeq, StdinRawReader};
use crate::screen::{Color, ColorMode};
use crate::term;
use crate::text_buffer::{char_render_width, TextBuffer};

pub const VERSION: &str = "0.4.3";

pub const HELP: &[(&str, &str)] = &[
    ("Ctrl-Q", "Quit"),
    ("Ctrl-S", "Save to file"),
    ("Ctrl-O", "Open text buffer"),
    ("Ctrl-X", "Next text buffer"),
    ("Alt-X", "Previous text buffer"),
    ("Ctrl-P or UP", "Move cursor up"),
    ("Ctrl-N or DOWN", "Move cursor down"),
    ("Ctrl-F or RIGHT", "Move cursor right"),
    ("Ctrl-B or LEFT", "Move cursor left"),
    ("Ctrl-A or Alt-LEFT or HOME", "Move cursor to head of line"),
    ("Ctrl-E or Alt-RIGHT or END", "Move cursor to end of line"),
    ("Ctrl-[ or Ctrl-V or PAGE DOWN", "Next page"),
    ("Ctrl-] or Alt-V or PAGE UP", "Previous page"),
    ("Alt-F or Ctrl-RIGHT", "Move cursor to next word"),
    ("Alt-B or Ctrl-LEFT", "Move cursor to previous word"),
    ("Alt-N or Ctrl-DOWN", "Move cursor to next paragraph"),
    ("Alt-P or Ctrl-UP", "Move cursor to previous paragraph"),
    ("Alt-<", "Move cursor to top of file"),
    ("Alt->", "Move cursor to bottom of file"),
    ("Ctrl-H or BACKSPACE", "Delete character"),
    ("Ctrl-D or DELETE", "Delete next character"),
    ("Ctrl-W", "Delete a word"),
    ("Ctrl-J", "Delete until head of line"),
    ("Ctrl-K", "Delete until end of line"),
    ("Ctrl-U", "Undo last change"),
    ("Ctrl-R", "Redo last undo change"),
    ("Ctrl-G", "Search text"),
    ("Ctrl-M", "New line"),
    ("Ctrl-L", "Refresh screen"),
    ("Ctrl-?", "Show this help"),
];

const HELP_KEY_WIDTH: usize = 30;

struct Message {
    text: String,
    is_error: bool,
    time: Instant,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Dir {
    Forward,
    Backward,
}

struct SearchState {
    query: Vec<char>,
    current: Option<(usize, usize)>,
}

/// A cell of a rendered row (tabs are expanded to spaces).
struct Cell {
    text: String,
    width: usize,
    hl: Highlight,
}

pub struct Editor {
    bufs: Vec<TextBuffer>,
    buf_idx: usize,
    rows: usize,
    cols: usize,
    color: ColorMode,
    message: Option<Message>,
    drawn_message: Option<String>,
    drawn_status: Option<String>,
    drawn_cursor: Option<(usize, usize)>,
    force_status: bool,
    quitting: bool,
    input: StdinRawReader,
    out: io::Stdout,
    search: Option<SearchState>,
    search_dir: Dir,
}

pub struct Terminal {
    raw: term::RawMode,
    alt_screen: bool,
}

impl Terminal {
    pub fn new() -> io::Result<Terminal> {
        let raw = term::RawMode::enable()?;
        Ok(Terminal { raw, alt_screen: false })
    }

    pub fn enter_alt_screen(&mut self) -> io::Result<()> {
        let mut out = io::stdout();
        out.write_all(b"\x1b[?1049h")?;
        out.flush()?;
        self.alt_screen = true;
        Ok(())
    }

    pub fn cleanup(&mut self) {
        if self.alt_screen {
            let mut out = io::stdout();
            let _ = out.write_all(b"\x1b[?1049l\x1b[H");
            let _ = out.flush();
            self.alt_screen = false;
        }
        self.raw.restore();
    }
}

impl Drop for Terminal {
    fn drop(&mut self) {
        self.cleanup();
    }
}

fn too_small_error(cols: usize, rows: usize) -> io::Error {
    io::Error::new(
        io::ErrorKind::Other,
        format!(
            "Screen {}x{} is too small. At least 1x3 is necessary in width x height",
            cols, rows
        ),
    )
}

impl Editor {
    pub fn new(input: StdinRawReader, rows: usize, cols: usize) -> Editor {
        Editor {
            bufs: Vec::new(),
            buf_idx: 0,
            rows,
            cols,
            color: ColorMode::detect(),
            message: None,
            drawn_message: None,
            drawn_status: None,
            drawn_cursor: None,
            force_status: false,
            quitting: false,
            input,
            out: io::stdout(),
            search: None,
            search_dir: Dir::Forward,
        }
    }

    /// Determine the window size, falling back to querying the terminal.
    pub fn query_window_size(input: &mut StdinRawReader) -> io::Result<(usize, usize)> {
        if let Some(size) = term::window_size_ioctl() {
            return Ok(size);
        }
        let mut out = io::stdout();
        out.write_all(b"\x1b[9999C\x1b[9999B\x1b[6n")?;
        out.flush()?;
        loop {
            let seq = input.read_seq()?;
            if let KeySeq::Cursor(r, c) = seq.key {
                return Ok((r, c));
            }
        }
    }

    pub fn check_size(rows: usize, cols: usize) -> io::Result<()> {
        if cols < 1 || rows < 3 {
            return Err(too_small_error(cols, rows));
        }
        Ok(())
    }

    pub fn open_files(&mut self, paths: &[String]) -> io::Result<()> {
        if paths.is_empty() {
            self.bufs.push(TextBuffer::empty());
        } else {
            for p in paths {
                self.bufs.push(TextBuffer::open(p)?);
            }
        }
        self.buf_idx = 0;
        self.set_message("Ctrl-? for help");
        Ok(())
    }

    fn buf(&self) -> &TextBuffer {
        &self.bufs[self.buf_idx]
    }

    fn buf_mut(&mut self) -> &mut TextBuffer {
        &mut self.bufs[self.buf_idx]
    }

    fn set_message<S: Into<String>>(&mut self, text: S) {
        self.message = Some(Message { text: text.into(), is_error: false, time: Instant::now() });
    }

    fn set_error_message<S: Into<String>>(&mut self, text: S) {
        self.message = Some(Message { text: text.into(), is_error: true, time: Instant::now() });
    }

    fn text_rows(&self) -> usize {
        self.rows - 1 - if self.message.is_some() { 1 } else { 0 }
    }

    fn seq(&self, c: Color) -> &'static str {
        c.sequence(self.color)
    }

    // ---- rendering -----------------------------------------------------------

    fn cells_of_row(&self, y: usize) -> Vec<Cell> {
        let buf = self.buf();
        let row = &buf.rows[y];
        let hls = buf.highlight_of(y);
        let mut match_hl: Vec<Option<Highlight>> = Vec::new();
        if let Some(search) = &self.search {
            if !search.query.is_empty() && row.len() >= search.query.len() {
                match_hl = vec![None; row.len()];
                let q = &search.query;
                let mut i = 0;
                while i + q.len() <= row.len() {
                    if row[i..i + q.len()] == q[..] {
                        let hl = if search.current == Some((i, y)) {
                            Highlight::CurrentMatch
                        } else {
                            Highlight::Match
                        };
                        for k in i..i + q.len() {
                            match_hl[k] = Some(hl);
                        }
                        i += 1;
                    } else {
                        i += 1;
                    }
                }
            }
        }
        let mut cells = Vec::with_capacity(row.len());
        let mut col = 0;
        for (i, &c) in row.iter().enumerate() {
            let hl = match_hl.get(i).copied().flatten().unwrap_or(hls[i]);
            if c == '\t' {
                let n = char_render_width(c, col);
                for _ in 0..n {
                    cells.push(Cell { text: " ".to_string(), width: 1, hl });
                }
                col += n;
            } else {
                let w = char_render_width(c, col);
                cells.push(Cell { text: c.to_string(), width: w, hl });
                col += w;
            }
        }
        cells
    }

    fn draw_text_row(&self, out: &mut Vec<u8>, y: usize) {
        let coloff = self.buf().coloff;
        let cells = self.cells_of_row(y);
        let mut cur = Highlight::Normal;
        let mut col = 0;
        for cell in &cells {
            let start = col;
            let end = col + cell.width;
            col = end;
            if end <= coloff {
                continue;
            }
            if end > coloff + self.cols {
                break;
            }
            if cell.hl != cur {
                if cur.has_background() {
                    out.extend_from_slice(self.seq(Color::Reset).as_bytes());
                }
                out.extend_from_slice(self.seq(Color::from_highlight(cell.hl)).as_bytes());
                cur = cell.hl;
            }
            let _ = start;
            out.extend_from_slice(cell.text.as_bytes());
        }
        out.extend_from_slice(self.seq(Color::Reset).as_bytes());
        out.extend_from_slice(b"\x1b[K");
    }

    fn draw_rows(&self, out: &mut Vec<u8>, from: usize, text_rows: usize) {
        let buf = self.buf();
        out.extend_from_slice(self.seq(Color::Reset).as_bytes());
        for r in from..text_rows {
            let y = buf.rowoff + r;
            out.extend_from_slice(format!("\x1b[{}H", r + 1).as_bytes());
            if y < buf.num_rows() {
                self.draw_text_row(out, y);
            } else {
                out.extend_from_slice(self.seq(Color::NonText).as_bytes());
                out.extend_from_slice(b"~");
                out.extend_from_slice(self.seq(Color::Reset).as_bytes());
                out.extend_from_slice(b"\x1b[K");
            }
        }
    }

    fn status_text(&self) -> String {
        let buf = self.buf();
        let left = format!(
            "\"{}\" - {}/{}{}",
            buf.display_name(),
            self.buf_idx + 1,
            self.bufs.len(),
            if buf.is_modified() { " (modified)" } else { "" }
        );
        let right = format!("{} {}/{}", buf.lang.name(), buf.cy + 1, buf.num_rows());
        let mut s = if left.len() > self.cols {
            if !left.is_char_boundary(self.cols) {
                crate::panic_like::slice_not_boundary("/workspace/src/screen.rs:209:25", self.cols, &left);
            }
            left[..self.cols].to_string()
        } else {
            left
        };
        while s.len() < self.cols {
            if self.cols - s.len() == right.len() {
                s.push_str(&right);
                break;
            }
            s.push(' ');
        }
        s
    }

    fn draw_status(&self, out: &mut Vec<u8>, text_rows: usize, status: &str) {
        out.extend_from_slice(format!("\x1b[{}H\x1b[7m", text_rows + 1).as_bytes());
        out.extend_from_slice(status.as_bytes());
        out.extend_from_slice(self.seq(Color::Reset).as_bytes());
    }

    fn draw_message(&self, out: &mut Vec<u8>) {
        let msg = match &self.message {
            Some(m) => m,
            None => return,
        };
        out.extend_from_slice(format!("\x1b[{}H", self.rows).as_bytes());
        if msg.is_error {
            out.extend_from_slice(self.seq(Color::ErrorMessage).as_bytes());
        }
        let text: String = msg.text.chars().take(self.cols).collect();
        out.extend_from_slice(text.as_bytes());
        if msg.is_error {
            out.extend_from_slice(self.seq(Color::Reset).as_bytes());
        }
        out.extend_from_slice(b"\x1b[K");
    }

    fn expire_message(&mut self) {
        if let Some(m) = &self.message {
            if m.time.elapsed().as_secs() > 5 {
                self.message = None;
            }
        }
    }

    /// Adjust scroll offsets. Returns true when they changed.
    fn scroll(&mut self, text_rows: usize) -> bool {
        let cols = self.cols;
        let buf = self.buf_mut();
        let (old_rowoff, old_coloff) = (buf.rowoff, buf.coloff);
        if buf.cy < buf.rowoff {
            buf.rowoff = buf.cy;
        }
        if buf.cy >= buf.rowoff + text_rows {
            buf.rowoff = buf.cy - text_rows + 1;
        }
        let rx = buf.rx();
        if rx < buf.coloff {
            buf.coloff = rx;
        }
        if rx >= buf.coloff + cols {
            let mut coloff = rx - cols + 1;
            if buf.cy < buf.num_rows() {
                let mut col = 0;
                for &c in &buf.rows[buf.cy] {
                    let w = char_render_width(c, col);
                    let (start, end) = (col, col + w);
                    if c != '\t' && start < coloff && coloff < end {
                        coloff = end;
                        break;
                    }
                    col = end;
                    if col > coloff {
                        break;
                    }
                }
            }
            buf.coloff = coloff;
        }
        buf.rowoff != old_rowoff || buf.coloff != old_coloff
    }

    fn cursor_screen_pos(&self) -> (usize, usize) {
        let buf = self.buf();
        (buf.cy - buf.rowoff + 1, buf.rx() - buf.coloff + 1)
    }

    fn render(&mut self) -> io::Result<()> {
        self.expire_message();
        let has_msg = self.message.is_some();
        let had_msg = self.drawn_message.is_some();
        let text_rows = self.text_rows();

        let mut dirty = self.buf_mut().dirty_start.take();
        let mut force_status = std::mem::take(&mut self.force_status);
        if has_msg != had_msg {
            force_status = true;
            if !has_msg {
                let exposed = self.buf().rowoff + text_rows - 1;
                dirty = Some(match dirty {
                    Some(d) => d.min(exposed),
                    None => exposed,
                });
            }
        }
        if self.scroll(text_rows) {
            dirty = Some(0);
        }
        self.buf_mut().update_highlight();

        let status = self.status_text();
        let status_changed = force_status || self.drawn_status.as_deref() != Some(status.as_str());
        let msg_text = self.message.as_ref().map(|m| m.text.clone());
        let msg_changed = msg_text != self.drawn_message;
        let cursor = self.cursor_screen_pos();

        let mut out: Vec<u8> = Vec::new();
        if dirty.is_none() && !status_changed && !msg_changed {
            if self.drawn_cursor != Some(cursor) {
                out.extend_from_slice(format!("\x1b[{};{}H", cursor.0, cursor.1).as_bytes());
                self.drawn_cursor = Some(cursor);
                self.out.write_all(&out)?;
                self.out.flush()?;
            }
            return Ok(());
        }

        out.extend_from_slice(b"\x1b[?25l");
        if let Some(d) = dirty {
            let rowoff = self.buf().rowoff;
            let from = if d > rowoff { d - rowoff } else { 0 };
            if from < text_rows {
                self.draw_rows(&mut out, from, text_rows);
            } else {
                out.extend_from_slice(self.seq(Color::Reset).as_bytes());
            }
        }
        if status_changed {
            self.draw_status(&mut out, text_rows, &status);
            self.drawn_status = Some(status);
        }
        if msg_changed && has_msg {
            self.draw_message(&mut out);
        }
        self.drawn_message = msg_text;
        out.extend_from_slice(format!("\x1b[{};{}H\x1b[?25h", cursor.0, cursor.1).as_bytes());
        self.drawn_cursor = Some(cursor);
        self.out.write_all(&out)?;
        self.out.flush()?;
        Ok(())
    }

    /// Initial screen when no file is given: shows the welcome message.
    fn render_welcome(&mut self) -> io::Result<()> {
        let text_rows = self.text_rows();
        let mut out: Vec<u8> = Vec::new();
        out.extend_from_slice(b"\x1b[?25l");
        out.extend_from_slice(self.seq(Color::Reset).as_bytes());
        for r in 0..text_rows {
            out.extend_from_slice(format!("\x1b[{}H", r + 1).as_bytes());
            if r == text_rows / 3 {
                let msg = format!("Kiro editor -- version {}", VERSION);
                let msg: String = msg.chars().take(self.cols).collect();
                let padding = (self.cols - msg.len()) / 2;
                if padding > 0 {
                    out.extend_from_slice(self.seq(Color::NonText).as_bytes());
                    out.extend_from_slice(b"~");
                    out.extend_from_slice(self.seq(Color::Reset).as_bytes());
                    for _ in 0..padding - 1 {
                        out.push(b' ');
                    }
                }
                out.extend_from_slice(msg.as_bytes());
            } else {
                out.extend_from_slice(self.seq(Color::NonText).as_bytes());
                out.extend_from_slice(b"~");
            }
            out.extend_from_slice(b"\x1b[K");
        }
        out.extend_from_slice(self.seq(Color::Reset).as_bytes());
        let status = self.status_text();
        self.draw_status(&mut out, text_rows, &status);
        self.drawn_status = Some(status);
        self.draw_message(&mut out);
        self.drawn_message = self.message.as_ref().map(|m| m.text.clone());
        out.extend_from_slice(b"\x1b[H\x1b[?25h");
        self.drawn_cursor = Some((1, 1));
        self.out.write_all(&out)?;
        self.out.flush()?;
        Ok(())
    }

    fn render_help(&mut self) -> io::Result<()> {
        let text_rows = self.text_rows();
        let max_len = HELP
            .iter()
            .map(|(_, d)| HELP_KEY_WIDTH + 2 + d.len())
            .max()
            .unwrap_or(0);
        let indent = if self.cols > max_len { (self.cols - max_len) / 2 } else { 0 };
        let top = if text_rows > HELP.len() { (text_rows - HELP.len()) / 2 } else { 0 };
        let mut out: Vec<u8> = Vec::new();
        for r in 0..text_rows {
            out.extend_from_slice(format!("\x1b[{}H", r + 1).as_bytes());
            if r >= top && r - top < HELP.len() {
                let (key, desc) = HELP[r - top];
                let mut remaining = self.cols - indent;
                for _ in 0..indent {
                    out.push(b' ');
                }
                let key_col = format!("{:<width$}", key, width = HELP_KEY_WIDTH);
                let take = key_col.len().min(remaining);
                out.extend_from_slice(self.seq(Color::Special).as_bytes());
                out.extend_from_slice(key_col[..take].as_bytes());
                out.extend_from_slice(self.seq(Color::Reset).as_bytes());
                remaining -= take;
                let rest = format!(": {}", desc);
                let rest: String = rest.chars().take(remaining).collect();
                out.extend_from_slice(rest.as_bytes());
            }
            out.extend_from_slice(b"\x1b[K");
        }
        self.out.write_all(&out)?;
        self.out.flush()?;
        Ok(())
    }

    // ---- window ----------------------------------------------------------------

    fn refresh_window_size(&mut self) -> io::Result<()> {
        let (rows, cols) = Editor::query_window_size(&mut self.input)?;
        Editor::check_size(rows, cols)?;
        self.rows = rows;
        self.cols = cols;
        Ok(())
    }

    fn refresh_screen(&mut self) -> io::Result<()> {
        self.refresh_window_size()?;
        self.message = None;
        self.buf_mut().mark_all_dirty();
        self.force_status = true;
        Ok(())
    }

    // ---- prompts ---------------------------------------------------------------

    fn prompt_cursor(&mut self, prefix: &str, input: &[char]) -> io::Result<()> {
        let col = prefix.chars().count() + input.len() + 1;
        self.out.write_all(format!("\x1b[{};{}H", self.rows, col).as_bytes())?;
        self.out.flush()
    }

    /// Generic prompt. `on_key` is called after each key with the current input and
    /// the key that was pressed (before rendering). Returns None when canceled.
    fn prompt<F>(&mut self, prefix: &str, suffix: &str, mut on_key: F) -> io::Result<Option<String>>
    where
        F: FnMut(&mut Editor, &[char], PromptEvent),
    {
        let mut input: Vec<char> = Vec::new();
        loop {
            let text: String = input.iter().collect();
            self.set_message(format!("{}{}{}", prefix, text, suffix));
            self.render()?;
            self.prompt_cursor(prefix, &input)?;
            let seq = self.input.read_seq()?;
            let event = match seq.key {
                KeySeq::Key(b'\r') => return Ok(Some(input.iter().collect())),
                KeySeq::Key(0x1b) | KeySeq::Key(0x07) | KeySeq::Key(0x11) => return Ok(None),
                KeySeq::Key(0x7f) | KeySeq::Key(0x08) | KeySeq::DeleteKey => {
                    input.pop();
                    PromptEvent::Changed
                }
                KeySeq::Key(0x17) => {
                    while input.last().map_or(false, |c| c.is_whitespace()) {
                        input.pop();
                    }
                    while input.last().map_or(false, |c| !c.is_whitespace()) {
                        input.pop();
                    }
                    PromptEvent::Changed
                }
                KeySeq::Key(0x0a) => {
                    input.clear();
                    PromptEvent::Changed
                }
                KeySeq::Key(b) if (0x20..=0x7e).contains(&b) => {
                    input.push(b as char);
                    PromptEvent::Changed
                }
                KeySeq::Utf8Key(c) => {
                    input.push(c);
                    PromptEvent::Changed
                }
                KeySeq::RightKey | KeySeq::Key(0x06) | KeySeq::Key(0x0e) => PromptEvent::Forward,
                KeySeq::LeftKey | KeySeq::Key(0x02) | KeySeq::Key(0x10) => PromptEvent::Backward,
                _ => PromptEvent::Other,
            };
            on_key(self, &input, event);
        }
    }

    fn save(&mut self) -> io::Result<()> {
        if self.buf().path.is_none() {
            let name = self.prompt("Save as: ", " (^G or ESC to cancel)", |_, _, _| {})?;
            match name {
                None => {
                    self.set_message("");
                    return Ok(());
                }
                Some(n) if n.is_empty() => {
                    self.set_message("");
                    return Ok(());
                }
                Some(n) => {
                    self.buf_mut().set_path(n);
                    self.buf_mut().mark_all_dirty();
                }
            }
        }
        match self.buf_mut().save() {
            Ok(n) => {
                let path = self.buf().path.clone().unwrap_or_default();
                self.set_message(format!("{} bytes written to {}", n, path));
            }
            Err(e) => {
                self.set_error_message(format!("Could not save: {}", e));
            }
        }
        Ok(())
    }

    fn open_prompt(&mut self) -> io::Result<()> {
        let name = self.prompt(
            "Open: ",
            " (Empty name for new text buffer, ^G or ESC to cancel)",
            |_, _, _| {},
        )?;
        match name {
            None => {
                self.set_message("Canceled");
            }
            Some(n) => {
                let buf = if n.is_empty() { TextBuffer::empty() } else { TextBuffer::open(&n)? };
                self.bufs.push(buf);
                self.buf_idx = self.bufs.len() - 1;
                self.message = None;
                self.buf_mut().mark_all_dirty();
                self.force_status = true;
            }
        }
        Ok(())
    }

    fn find_match(&self, query: &[char], from: (usize, usize), dir: Dir, inclusive: bool) -> Option<(usize, usize)> {
        let buf = self.buf();
        let n = buf.num_rows();
        if n == 0 || query.is_empty() {
            return None;
        }
        let (fx, fy) = (from.0, from.1.min(n - 1));
        let find_in = |y: usize, lo: usize, hi: usize, backward: bool| -> Option<(usize, usize)> {
            let row = &buf.rows[y];
            let hi = hi.min(row.len());
            if lo > hi || hi - lo < query.len() {
                return None;
            }
            let last_start = hi - query.len();
            if backward {
                let mut i = last_start as isize;
                while i >= lo as isize {
                    let s = i as usize;
                    if row[s..s + query.len()] == query[..] {
                        return Some((s, y));
                    }
                    i -= 1;
                }
            } else {
                for s in lo..=last_start {
                    if row[s..s + query.len()] == query[..] {
                        return Some((s, y));
                    }
                }
            }
            None
        };
        match dir {
            Dir::Forward => {
                let start = if inclusive { fx } else { fx + 1 };
                if let Some(m) = find_in(fy, start, usize::MAX, false) {
                    return Some(m);
                }
                for k in 1..=n {
                    let y = (fy + k) % n;
                    if let Some(m) = find_in(y, 0, usize::MAX, false) {
                        return Some(m);
                    }
                }
                None
            }
            Dir::Backward => {
                // positions strictly before fx, but allow a match ending before fx
                let hi = fx + query.len() - 1;
                if let Some(m) = find_in(fy, 0, hi, true) {
                    return Some(m);
                }
                for k in 1..=n {
                    let y = (fy + n - (k % n)) % n;
                    if let Some(m) = find_in(y, 0, usize::MAX, true) {
                        return Some(m);
                    }
                }
                None
            }
        }
    }

    fn search(&mut self) -> io::Result<()> {
        let orig = {
            let b = self.buf();
            (b.cx, b.cy, b.rowoff, b.coloff)
        };
        self.search = Some(SearchState { query: Vec::new(), current: None });
        self.search_dir = Dir::Forward;
        let result = self.prompt(
            "Search: ",
            " (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)",
            |ed, input, event| {
                ed.buf_mut().mark_all_dirty();
                match event {
                    PromptEvent::Changed => {
                        let query: Vec<char> = input.to_vec();
                        let (cx, cy) = (ed.buf().cx, ed.buf().cy);
                        let found = ed.find_match(&query, (cx, cy), ed.search_dir, true);
                        if let Some((x, y)) = found {
                            let b = ed.buf_mut();
                            b.cx = x;
                            b.cy = y;
                        }
                        if let Some(s) = &mut ed.search {
                            s.query = query;
                            s.current = found;
                        }
                    }
                    PromptEvent::Forward | PromptEvent::Backward => {
                        let dir = if event == PromptEvent::Forward { Dir::Forward } else { Dir::Backward };
                        ed.search_dir = dir;
                        let query = ed.search.as_ref().map(|s| s.query.clone()).unwrap_or_default();
                        if query.is_empty() {
                            return;
                        }
                        let (cx, cy) = (ed.buf().cx, ed.buf().cy);
                        let found = ed.find_match(&query, (cx, cy), dir, false);
                        if let Some((x, y)) = found {
                            let b = ed.buf_mut();
                            b.cx = x;
                            b.cy = y;
                        }
                        if let Some(s) = &mut ed.search {
                            s.current = found;
                        }
                    }
                    PromptEvent::Other => {}
                }
            },
        )?;
        let found = self.search.as_ref().and_then(|s| s.current);
        self.search = None;
        self.buf_mut().mark_all_dirty();
        match result {
            None => {
                let b = self.buf_mut();
                b.cx = orig.0;
                b.cy = orig.1;
                b.rowoff = orig.2;
                b.coloff = orig.3;
                self.set_message("Canceled");
            }
            Some(q) if q.is_empty() => {
                self.set_message("Canceled");
            }
            Some(_) => {
                if found.is_some() {
                    self.set_message("Found");
                } else {
                    self.set_message("Not found");
                }
            }
        }
        Ok(())
    }

    fn show_help(&mut self) -> io::Result<()> {
        self.render_help()?;
        // any key dismisses the help
        let _ = self.input.read_seq()?;
        self.buf_mut().mark_all_dirty();
        Ok(())
    }

    fn switch_buffer(&mut self, next: bool) {
        if self.bufs.len() <= 1 {
            self.set_message("No other buffer is opened");
            return;
        }
        self.buf_mut().finish_edit();
        if next {
            self.buf_idx = (self.buf_idx + 1) % self.bufs.len();
        } else {
            self.buf_idx = (self.buf_idx + self.bufs.len() - 1) % self.bufs.len();
        }
        self.buf_mut().mark_all_dirty();
        self.force_status = true;
    }

    // ---- key handling -------------------------------------------------------------

    /// Returns false when the editor should quit.
    fn handle_key(&mut self, seq: InputSeq) -> io::Result<bool> {
        let text_rows = self.text_rows();
        let was_quitting = self.quitting;
        self.quitting = false;
        match (seq.key, seq.ctrl, seq.alt) {
            (KeySeq::Key(0x11), _, false) => {
                let any_modified = self.bufs.iter().any(|b| b.is_modified());
                if any_modified && !was_quitting {
                    self.quitting = true;
                    self.set_error_message(
                        "At least one file has unsaved changes! Press ^Q again to quit or ^S to save",
                    );
                } else {
                    return Ok(false);
                }
            }
            (KeySeq::Key(0x13), _, false) => self.save()?,
            (KeySeq::Key(0x0f), _, false) => self.open_prompt()?,
            (KeySeq::Key(0x18), _, false) => self.switch_buffer(true),
            (KeySeq::Key(b'x'), false, true) => self.switch_buffer(false),
            (KeySeq::Key(0x10), _, false) | (KeySeq::UpKey, false, _) => self.buf_mut().move_up(),
            (KeySeq::Key(0x0e), _, false) | (KeySeq::DownKey, false, _) => self.buf_mut().move_down(),
            (KeySeq::Key(0x06), _, false) | (KeySeq::RightKey, false, _) => self.buf_mut().move_right(),
            (KeySeq::Key(0x02), _, false) | (KeySeq::LeftKey, false, _) => self.buf_mut().move_left(),
            (KeySeq::Key(0x01), _, false) | (KeySeq::HomeKey, false, _) => self.buf_mut().move_home(),
            (KeySeq::Key(0x05), _, false) | (KeySeq::EndKey, false, _) => self.buf_mut().move_end(),
            (KeySeq::Key(0x1d), _, false) | (KeySeq::Key(0x16), _, false) | (KeySeq::PageDownKey, _, _) => {
                self.buf_mut().page_down(text_rows)
            }
            (KeySeq::Key(0x1b), _, false) | (KeySeq::Key(b'v'), false, true) | (KeySeq::PageUpKey, _, _) => {
                self.buf_mut().page_up(text_rows)
            }
            (KeySeq::Key(b'f'), false, true) | (KeySeq::RightKey, true, _) => self.buf_mut().next_word(),
            (KeySeq::Key(b'b'), false, true) | (KeySeq::LeftKey, true, _) => self.buf_mut().prev_word(),
            (KeySeq::Key(b'n'), false, true) | (KeySeq::DownKey, true, _) => self.buf_mut().next_paragraph(),
            (KeySeq::Key(b'p'), false, true) | (KeySeq::UpKey, true, _) => self.buf_mut().prev_paragraph(),
            (KeySeq::Key(b'<'), false, true) => self.buf_mut().move_top(),
            (KeySeq::Key(b'>'), false, true) => self.buf_mut().move_bottom(),
            (KeySeq::Key(0x08), _, false) | (KeySeq::Key(0x7f), _, false) => self.buf_mut().delete_char(),
            (KeySeq::Key(0x04), _, false) | (KeySeq::DeleteKey, _, _) => self.buf_mut().delete_right_char(),
            (KeySeq::Key(0x17), _, false) => self.buf_mut().delete_word(),
            (KeySeq::Key(0x0a), _, false) => self.buf_mut().delete_until_head_of_line(),
            (KeySeq::Key(0x0b), _, false) => self.buf_mut().delete_until_end_of_line(),
            (KeySeq::Key(0x15), _, false) => {
                if !self.buf_mut().undo() {
                    self.set_message("No older change");
                }
            }
            (KeySeq::Key(0x12), _, false) => {
                if !self.buf_mut().redo() {
                    self.set_message("Buffer is already newest");
                }
            }
            (KeySeq::Key(0x07), _, false) => self.search()?,
            (KeySeq::Key(b'\r'), _, false) => self.buf_mut().insert_newline(),
            (KeySeq::Key(0x0c), _, false) => self.refresh_screen()?,
            (KeySeq::Key(0x1f), _, false) => self.show_help()?,
            (KeySeq::Key(b'\t'), _, false) => self.buf_mut().insert_char('\t'),
            (KeySeq::Key(b), false, false) if b < 0x20 || b == 0x7f => {
                let msg = format!("Key '{}' not mapped", seq);
                self.set_error_message(msg);
            }
            (KeySeq::Key(b), false, false) => self.buf_mut().insert_char(b as char),
            (KeySeq::Utf8Key(c), false, false) => self.buf_mut().insert_char(c),
            (KeySeq::Key(_), false, true) | (KeySeq::Utf8Key(_), false, true) => {
                let msg = format!("Key '{}' not mapped", seq);
                self.set_error_message(msg);
            }
            (KeySeq::HomeKey, true, _) | (KeySeq::EndKey, true, _) => {
                let msg = format!("Key '{}' not mapped", seq);
                self.set_error_message(msg);
            }
            _ => {}
        }
        Ok(true)
    }

    pub fn run(&mut self, show_welcome: bool) -> io::Result<()> {
        if show_welcome {
            self.render_welcome()?;
        } else {
            self.buf_mut().mark_all_dirty();
            self.force_status = true;
            self.render()?;
        }
        let mut first = true;
        loop {
            let seq = self.input.read_seq()?;
            if term::take_resized() {
                self.refresh_screen()?;
            }
            if !self.handle_key(seq)? {
                break;
            }
            if first {
                self.buf_mut().mark_all_dirty();
                first = false;
            }
            self.render()?;
        }
        Ok(())
    }
}

