mod width_table;

use std::io::Write;

use editor::{Editor, Terminal, HELP, VERSION};
use input::StdinRawReader;

fn print_help(prog: &str) {
    let mut out = String::new();
    out.push_str(&format!("{}: A tiny UTF-8 terminal text editor\n\n", prog));
    out.push_str("Kiro is a tiny UTF-8 text editor on terminals for Unix-like systems.\n");
    out.push_str("Specify file paths to edit as a command argument or run without argument to\n");
    out.push_str("start to write a new text.\n");
    out.push_str("Help can show up with key mapping Ctrl-?.\n\n");
    out.push_str("Usage:\n");
    out.push_str(&format!("    {} [options] [FILES...]\n\n", prog));
    out.push_str("Mappings:\n");
    for (key, desc) in HELP {
        out.push_str(&format!("    {:<30}: {}\n", key, desc));
    }
    out.push_str("\nOptions:\n");
    out.push_str("    -v, --version       Print version\n");
    out.push_str("    -h, --help          Print this help\n");
    print!("{}", out);
}

enum Opts {
    Run(Vec<String>),
    Help,
    Version,
}

fn parse_args(args: &[String]) -> Result<Opts, String> {
    let mut files = Vec::new();
    let mut help = false;
    let mut version = false;
    let mut iter = args.iter();
    let mut only_free = false;
    while let Some(arg) = iter.next() {
        if only_free || arg == "-" || !arg.starts_with('-') {
            files.push(arg.clone());
            continue;
        }
        if arg == "--" {
            only_free = true;
            continue;
        }
        if let Some(long) = arg.strip_prefix("--") {
            let (name, value) = match long.find('=') {
                Some(i) => (&long[..i], Some(&long[i + 1..])),
                None => (long, None),
            };
            match name {
                "help" | "version" => {
                    if value.is_some() {
                        return Err(format!("Option '{}' does not take an argument", name));
                    }
                    if name == "help" {
                        help = true;
                    } else {
                        version = true;
                    }
                }
                _ => return Err(format!("Unrecognized option: '{}'", name)),
            }
            continue;
        }
        // short options cluster
        for c in arg[1..].chars() {
            match c {
                'h' => help = true,
                'v' => version = true,
                _ => return Err(format!("Unrecognized option: '{}'", c)),
            }
        }
    }
    if version {
        Ok(Opts::Version)
    } else if help {
        Ok(Opts::Help)
    } else {
        Ok(Opts::Run(files))
    }
}

fn run(files: Vec<String>) -> std::io::Result<()> {
    term::install_resize_handler();
    let mut terminal = Terminal::new()?;
    let mut input = StdinRawReader::new();
    let (rows, cols) = Editor::query_window_size(&mut input)?;
    Editor::check_size(rows, cols)?;
    terminal.enter_alt_screen()?;
    let mut editor = Editor::new(input, rows, cols);
    let show_welcome = files.is_empty();
    editor.open_files(&files)?;
    editor.run(show_welcome)?;
    terminal.cleanup();
    Ok(())
}

fn main() {
    panic_like::install_hook();
    let args: Vec<String> = std::env::args().collect();
    let prog = args.get(0).cloned().unwrap_or_else(|| "kiro".to_string());
    match parse_args(&args[1..]) {
        Err(msg) => {
            eprintln!("Error: {}. Please see --help for more details", msg);
            std::process::exit(1);
        }
        Ok(Opts::Version) => {
            println!("{}", VERSION);
        }
        Ok(Opts::Help) => {
            print_help(&prog);
        }
        Ok(Opts::Run(files)) => {
            if let Err(e) = run(files) {
                let _ = std::io::stdout().flush();
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    }
}
