        // search cycles through that position as well.
        let total = n + 1;
        let (fx, fy) = (from.0, from.1.min(n));
        let find_in = |y: usize, lo: usize, hi: usize, backward: bool| -> Option<(usize, usize)> {
            if y >= n {
                return None;
            }
            let row = &buf.rows[y];
            let hi = hi.min(row.len());
            if lo > hi || hi - lo < query.len() {
                return None;
            }
            let last_start = hi - query.len();
            if backward {
                let mut i = last_start as isize;
                while i >= lo as isize {
                    let s = i as usize;
                    if row[s..s + query.len()] == query[..] {
                        return Some((s, y));
                    }
                    i -= 1;
                }
